{"implementation": "def solve(case):
    lines = case.get('lines', [])
    trajectory = []
    valid = True
    error_line = None
    allowed_types = {"Thought", "Action", "Observation", "Final"}
    transitions = {
        "Thought": {"Action", "Final"},
        "Action": {"Observation"},
        "Observation": {"Thought", "Final"},
        "Final": set()
    }
    expected = {"Thought"}
    for i, line in enumerate(lines):
        if ':' in line:
            idx = line.index(':')
            type_ = line[:idx].strip()
            content = line[idx+1:].strip()
        else:
            type_ = None
            content = line.strip()
        if type_ is None or type_ not in allowed_types:
            if error_line is None:
                error_line = i
                valid = False
            trajectory.append({"type": type_ if type_ else "", "content": content})
            continue
        if type_ not in expected:
            if error_line is None:
                error_line = i
                valid = False
            trajectory.append({"type": type_, "content": content})
            continue
        trajectory.append({"type": type_, "content": content})
        expected = transitions[type_]
    if valid and (len(trajectory) == 0 or trajectory[-1]["type"] != "Final"):
        valid = False
        if error_line is None:
            error_line = len(lines) - 1 if lines else 0
    if valid and len(trajectory) > 0 and trajectory[0]["type"] != "Thought":
        valid = False
        error_line = 0
    return {
        "error_line": error_line,
        "trajectory": trajectory,
        "valid": valid
    }"}
